SELECT * FROM settlement_pending_data


        AND business_type = #{businessType}


        AND settlement_status = #{settlementStatus}


        AND priority = #{priority}


        AND currency_code = #{currencyCode}


        AND account_id = #{accountId}


        AND DATE(create_time) >= #{startDate}


        AND DATE(create_time) <= #{endDate}


        AND org_id = #{orgId}


ORDER BY create_time DESC

SELECT * FROM settlement_pending_data
WHERE settlement_status = #{settlementStatus} AND org_id = #{orgId}
ORDER BY create_time DESC

SELECT * FROM settlement_pending_data
WHERE settlement_amount >= #{minAmount}
AND settlement_status IN ('PENDING', 'APPROVED')
AND org_id = #{orgId}
ORDER BY settlement_amount DESC

SELECT business_type, COUNT(*) as count, SUM(settlement_amount) as totalAmount, AVG(settlement_amount) as avgAmount FROM settlement_pending_data WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY business_type ORDER BY totalAmount DESC

SELECT currency_code, COUNT(*) as count, SUM(settlement_amount) as totalAmount, AVG(settlement_amount) as avgAmount FROM settlement_pending_data WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY currency_code ORDER BY totalAmount DESC

SELECT settlement_status, COUNT(*) as count, SUM(settlement_amount) as totalAmount, AVG(settlement_amount) as avgAmount FROM settlement_pending_data WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY settlement_status ORDER BY count DESC
